actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate Oklahoma state additions
            double additions = 0.0;

            // Oklahoma requires addback of interest on U.S. government obligations
            // (U.S. obligations are not taxable federally but may be to states)
            // Per OAC 710:50-17-51, add interest income from U.S. obligations
            // additions += revenue.federal_bond_interest;

            // Oklahoma requires addback of state income tax refunds if included in federal income
            // additions += result.state_tax_refund;

            // Oklahoma may require addback of IRC 199A deduction depending on conformity
            // (OK partially decouples from IRC 199A)
            // additions += result.section_199a_deduction;

            apportionment.state_additions = additions;

            // Calculate Oklahoma state subtractions
            double subtractions = 0.0;

            // Subtract Oklahoma municipal bond interest
            // (exempt from OK tax but may have been included in federal income)
            // Per OAC 710:50-17-51, subtract interest from OK obligations
            // subtractions += revenue.ok_municipal_interest;

            // Subtract qualified dividends from affiliated corporations
            // (OK allows deduction for certain intercorporate dividends)
            // subtractions += result.affiliated_dividend_deduction;

            // Subtract income from U.S. government obligations if included in federal income
            // subtractions += revenue.federal_bond_interest_if_included_federally;

            apportionment.state_subtractions = subtractions;

            // Oklahoma uses 4% flat rate
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract OK state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
